import { z } from "zod";

/** The kinds `resolveNowActivity` can resolve to; `shown` rows carry one so exposure is what the screen actually said. */
export const NOW_RESOLUTION_KINDS = [
  "session",
  "routine_step",
  "commitment",
  "travel",
  "sleep",
  "recommended",
  "free"
] as const;
export type NowResolutionKind = (typeof NOW_RESOLUTION_KINDS)[number];

/**
 * One `shown` beacon: the portal telling the offer log what the open Now page resolved to.
 *
 * `clientId` is generated by the browser per distinct shown key and becomes the row's `command_id`, so a retried or
 * doubled request writes one row (idempotent on command_id, event, target_id). `suppressedBy` is the engine's primary
 * when the screen showed something else on top of it (a commitment, sleep, a routine step).
 *
 * Strict: a field this endpoint never agreed to store is a 400, not a silent drop.
 */
export const offerLogShownSchema = z
  .object({
    clientId: z.string().uuid(),
    surface: z.literal("portal"),
    resolutionKind: z.enum(NOW_RESOLUTION_KINDS),
    targetType: z.string().trim().min(1).max(64),
    targetId: z.string().trim().min(1).max(200),
    label: z.string().max(300),
    executionOptionId: z.string().min(1).max(200).optional(),
    suppressedBy: z
      .object({
        targetType: z.string().trim().min(1).max(64),
        targetId: z.string().trim().min(1).max(200),
        executionOptionId: z.string().min(1).max(200).optional(),
        label: z.string().max(300).optional()
      })
      .strict()
      .optional()
  })
  .strict();
export type OfferLogShown = z.infer<typeof offerLogShownSchema>;
